/* The tar is placed right after the marker; see linux-desktop-setup. lxdesk-desktop-pack-stamp.h is generated by the
 * bundleDesktopPackages Gradle task and changes whenever a pack changes, so this file is reassembled. */
#include "lxdesk-desktop-pack-stamp.h"

     .global lxdesk_desktop_pack
     .section .rodata
 lxdesk_desktop_pack:
 #if defined __i686__ && LXDESK_PACK_I686
     .ascii "LXDESK_DESKTOP_PACK_BEGIN_V1\n"
     .incbin "desktop-pack-i686.tar"
 #elif defined __x86_64__ && LXDESK_PACK_X86_64
     .ascii "LXDESK_DESKTOP_PACK_BEGIN_V1\n"
     .incbin "desktop-pack-x86_64.tar"
 #elif defined __aarch64__ && LXDESK_PACK_AARCH64
     .ascii "LXDESK_DESKTOP_PACK_BEGIN_V1\n"
     .incbin "desktop-pack-aarch64.tar"
 #elif defined __arm__ && LXDESK_PACK_ARM
     .ascii "LXDESK_DESKTOP_PACK_BEGIN_V1\n"
     .incbin "desktop-pack-arm.tar"
 #endif
     .byte 0
